describe('Modal Dialog Animation', () => {
  beforeEach(() => {
    cy.visit('/modal-test');
  });

  it('should open modal with animation and display content', () => {
    // Click the button to trigger modal
    cy.get('[data-testid="open-modal-btn"]').click();

    // Wait for modal to appear with animation
    cy.get('[data-testid="modal-overlay"]').should('be.visible');
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Verify modal has correct animation class
    cy.get('[data-testid="modal-overlay"]').should('have.class', 'modal-fade-in');

    // Verify modal contains expected content
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');
    cy.get('[data-testid="modal-body"]').should('contain', 'Modal body content');

    // Verify close button is present
    cy.get('[data-testid="close-modal-btn"]').should('be.visible');

    // Verify modal is centered on the screen
    cy.get('[data-testid="modal-overlay"]').should('have.css', 'transform', 'translate(-50%, -50%)');

    // Verify modal has correct dimensions
    cy.get('[data-testid="modal-overlay"]').should('have.css', 'width', '600px');
    cy.get('[data-testid="modal-overlay"]').should('have.css', 'height', '400px');

    // Verify modal is not covering the entire screen
    cy.get('[data-testid="modal-overlay"]').should('not.have.style', 'top', '0');

    // Verify modal is not visible when clicking outside
    cy.get('[data-testid="background-container"]').click();
    cy.get('[data-testid="modal-overlay"]').should('not.exist');
  });

  it('should close modal with animation and remove from DOM', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-overlay"]').should('be.visible');

    // Verify modal is visible
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Click close button
    cy.get('[data-testid="close-modal-btn"]').click();

    // Wait for close animation
    cy.get('[data-testid="modal-overlay"]').should('have.class', 'modal-fade-out');

    // Verify modal is no longer visible
    cy.get('[data-testid="modal-overlay"]').should('not.exist');

    // Verify modal content is removed from DOM
    cy.get('[data-testid="modal-content"]').should('not.exist');

    // Verify modal was removed from the DOM
    cy.get('[data-testid="modal-overlay"]').should('not.exist');

    // Verify background container is visible again
    cy.get('[data-testid="background-container"]').should('be.visible');
  });
});
